/*
 * node_modules/express — Express-shaped router for the SEVM stack.
 *
 * Full compatibility layer on top of the node:http surface in
 * node_modules/net: middleware chain (app.use), path parameters
 * (/items/:id), query strings, body parsing (express.json/urlencoded/text),
 * static file serving (express.static), res helpers
 * (set/type/attachment/redirect/status/json/send/end), template engines
 * (app.engine/app.set('view engine')/res.render with a built-in mini-EJS),
 * subdomain vhosts (express.vhost), route param middleware (app.param) and
 * error middleware (err, req, res, next with arity 4).
 */

import { createServer } from '../net/index.js';
import * as fs from '../mochifs/index.js';

const MIME = {
    '.html': 'text/html; charset=utf-8', '.htm': 'text/html; charset=utf-8',
    '.js': 'application/javascript', '.mjs': 'application/javascript',
    '.css': 'text/css', '.json': 'application/json',
    '.png': 'image/png', '.jpg': 'image/jpeg', '.jpeg': 'image/jpeg',
    '.gif': 'image/gif', '.svg': 'image/svg+xml', '.ico': 'image/x-icon',
    '.txt': 'text/plain; charset=utf-8', '.map': 'application/json',
    '.woff': 'font/woff', '.woff2': 'font/woff2', '.ttf': 'font/ttf',
    '.webp': 'image/webp', '.avif': 'image/avif',
};

function extname(p) {
    const i = p.lastIndexOf('.');
    return i < 0 ? '' : p.slice(i).toLowerCase();
}

function mimeFor(path) {
    return MIME[extname(path)] || 'application/octet-stream';
}

/* /items/:id -> ^/items/([^/]+)$ with keys ['id']; '*' -> .* */
function compilePath(pattern) {
    const keys = [];
    const re = pattern
        .replace(/[.*+?^${}()|[\]\\]/g, (m) => (m === '*' ? '\u0000' : '\\' + m))
        .replace(/\u0000/g, '.*')
        .replace(/:([A-Za-z_][A-Za-z0-9_]*)/g, (m, k) => {
            keys.push(k);
            return '([^/]+)';
        });
    return { re: new RegExp('^' + re + '$'), keys };
}

function matchPath(pattern, path) {
    const { re, keys } = compilePath(pattern);
    const m = re.exec(path);
    if (!m) return null;
    const params = Object.create(null);
    for (let i = 0; i < keys.length; i++) params[keys[i]] = decodeURIComponent(m[i + 1]);
    return params;
}

/* parse the raw body string by content-type; idempotent per request */
function parseBody(req) {
    if (req._parsedBody !== undefined) return req._parsedBody;
    const ct = (req.headers['content-type'] || '').toLowerCase();
    let out;
    if (req.body && req.body.length) {
        if (ct.includes('application/json')) {
            try { out = JSON.parse(req.body); } catch (e) { out = {}; }
        } else if (ct.includes('application/x-www-form-urlencoded')) {
            out = Object.create(null);
            for (const pair of req.body.split('&')) {
                if (!pair) continue;
                const eq = pair.indexOf('=');
                const k = eq >= 0 ? pair.slice(0, eq) : pair;
                const v = eq >= 0 ? pair.slice(eq + 1) : '';
                out[decodeURIComponent(k.replace(/\+/g, ' '))] =
                    decodeURIComponent(v.replace(/\+/g, ' '));
            }
        } else out = req.body;
    } else out = {};
    req._parsedBody = out;
    return out;
}

/* ---- built-in mini-EJS: <%= %>, <%- %>, <% %>, <%% %%> ---- */
function renderMiniEJS(template, data) {
    const d = data || {};
    const esc = (s) => String(s == null ? '' : s)
        .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
    /* <%% %%> are literal; <%= %> -> output-escaped chunk; <%- %> -> raw chunk;
       <% code %> -> control chunk. All are evaluated in the generated function,
       so loop/if variables stay in scope. */
    const body = template
        .replace(/<%%/g, '\u0001').replace(/%%>/g, '\u0002')
        .replace(/<%=\s*([\s\S]*?)\s*%>/g, (m, e) => '<?js = ' + e + ' ?>')
        .replace(/<%-\s*([\s\S]*?)\s*%>/g, (m, e) => '<?js ~ ' + e + ' ?>')
        .replace(/<%([\s\S]*?)%>/g, (m, e) => '<?js ' + e + ' ?>')
        .replace(/\u0001/g, '<%').replace(/\u0002/g, '%>');
    const chunks = body.split(/(<\?js [\s\S]*?\?>)/g);
    let src = 'with(this){';
    for (const ch of chunks) {
        if (ch.startsWith('<?js ')) {
            const inner = ch.slice(5, -2).trim();
            if (inner.startsWith('=')) src += 'out+=' + escSrc(inner.slice(1).trim()) + ';';
            else if (inner.startsWith('~')) src += 'out+=String(' + inner.slice(1).trim() + ');';
            else src += inner + ';';
        } else if (ch) {
            src += 'out+=' + JSON.stringify(ch) + ';';
        }
    }
    src += '} return out;';
    const fn = new Function('out', 'escFn', 'data', src);
    return fn.call(d, '', esc, d);
}

function escSrc(expr) {
    return `escFn(String(${expr}))`;
}

/* ---- vhost: match Host header against a subdomain pattern ---- */
function hostMatches(pattern, host) {
    const h = String(host || '').toLowerCase().replace(/:\d+$/, '');
    const p = String(pattern || '').toLowerCase();
    if (p === h) return true;
    if (p.startsWith('*.')) {
        const suffix = p.slice(1);
        return h.endsWith(suffix) && h.length > suffix.length;
    }
    return false;
}

export function express() {
    /* stack entries: {method|null, path|null, fn} — method null => middleware */
    const stack = [];
    const engines = Object.create(null);          /* ext -> engine fn */
    const settings = Object.create(null);         /* app settings */
    const paramHandlers = Object.create(null);    /* param name -> [fn] */
    settings['view engine'] = '';
    settings['views'] = 'views';

    function layerMatched(l, req) {
        if (l.method) {
            if (l.method !== req.method) return false;
            if (l.path && !matchPath(l.path, req.path)) return false;
            return true;
        }
        if (l.path) {
            if (req.path !== l.path && !req.path.startsWith(l.path + '/')) return false;
        }
        return true;
    }

    function runParamHandlers(req, res, params, done) {
        const names = Object.keys(params || {});
        const toRun = names.filter((n) => paramHandlers[n]);
        let k = 0;
        const step = (err) => {
            if (err) return done(err);
            if (k >= toRun.length) return done(null);
            const name = toRun[k++];
            const fns = paramHandlers[name];
            let j = 0;
            const nextP = (e) => {
                if (e) return done(e);
                if (j >= fns.length) return step(null);
                try { fns[j++](req, res, nextP, params[name], name); }
                catch (e2) { done(e2); }
            };
            nextP();
        };
        step();
    }

    function dispatch(req, res, i, err) {
        if (err) {
            for (let k = i; k < stack.length; k++) {
                const l = stack[k];
                if (l.fn.length >= 4) {
                    try { l.fn(err, req, res, (e2) => dispatch(req, res, k + 1, e2)); }
                    catch (e2) { res.status(500).json({ error: String(e2 && e2.message ? e2.message : e2) }); }
                    return;
                }
            }
            res.status(500).json({ error: String(err && err.message ? err.message : err) });
            return;
        }
        if (i >= stack.length) {
            res.status(404).json({ error: 'Not Found', path: req.path });
            return;
        }
        const l = stack[i];
        /* error middleware (arity 4) are only reached via next(err); skip them here */
        if (l.fn.length >= 4) { dispatch(req, res, i + 1); return; }
        if (!layerMatched(l, req)) { dispatch(req, res, i + 1); return; }

        const routeParams = l.method ? matchPath(l.path, req.path) : null;
        if (routeParams) Object.assign(req.params, routeParams);

        const next = (e) => dispatch(req, res, i + 1, e);
        if (routeParams) {
            runParamHandlers(req, res, routeParams, (pe) => {
                if (pe) return next(pe);
                try { l.fn(req, res, next); }
                catch (e) { next(e); }
            });
        } else {
            try { l.fn(req, res, next); }
            catch (e) { next(e); }
        }
    }

    function app(req, res) {
        if (!req.params) req.params = Object.create(null);
        if (!req.query) req.query = Object.create(null);
        if (!req.body) req.body = '';
        if (!req.get) req.get = (k) => req.headers[String(k).toLowerCase()];
        if (!res.render) {
            res.render = (view, data, cb) => {
                if (typeof data === 'function') { cb = data; data = {}; }
                data = data || {};
                let name = String(view);
                let ext = extname(name);
                if (!ext) {
                    const ve = settings['view engine'];
                    ext = ve ? (ve.startsWith('.') ? ve : '.' + ve) : '.html';
                    name += ext;
                }
                const engine = engines[ext];
                if (!engine) {
                    const e = new Error('No engine registered for ' + ext);
                    if (cb) return cb(e);
                    res.status(500).json({ error: e.message });
                    return;
                }
                const viewsRoot = String(settings['views'] || 'views').replace(/\/$/, '');
                const full = viewsRoot + '/' + name;
                try {
                    if (!fs.existsSync(full)) {
                        const e = new Error('View not found: ' + name);
                        if (cb) return cb(e);
                        res.status(500).json({ error: e.message });
                        return;
                    }
                    const tpl = String(fs.readFileSync(full));
                    const html = engine(tpl, data, { root: viewsRoot, name });
                    if (cb) return cb(null, html);
                    res.type('text/html').send(html);
                } catch (e) {
                    if (cb) return cb(e);
                    res.status(500).json({ error: String(e && e.message ? e.message : e) });
                }
            };
        }
        dispatch(req, res, 0);
    }

    for (const m of ['get', 'post', 'put', 'delete', 'patch', 'head', 'options']) {
        app[m] = (path, ...fns) => {
            for (const fn of fns) stack.push({ method: m.toUpperCase(), path, fn });
            return app;
        };
    }

    app.use = (arg, ...fns) => {
        let path = null;
        if (typeof arg === 'string') path = arg;
        else fns = [arg, ...fns];
        for (const fn of fns) {
            if (path && typeof fn === 'function' && '__mount' in fn) fn.__mount = path;
            stack.push({ method: null, path, fn });
        }
        return app;
    };

    app.param = (name, fn) => {
        if (!paramHandlers[name]) paramHandlers[name] = [];
        paramHandlers[name].push(fn);
        return app;
    };

    app.engine = (ext, fn) => {
        engines[ext.startsWith('.') ? ext : '.' + ext] = fn;
        return app;
    };

    app.set = (key, value) => {
        if (typeof key === 'object') { Object.assign(settings, key); return app; }
        settings[String(key)] = value;
        return app;
    };

    app.get = (key, ...fns) => {
        if (fns.length === 0 && typeof key === 'string' && Object.prototype.hasOwnProperty.call(settings, key))
            return settings[key];
        if (fns.length === 0) return undefined;
        for (const fn of fns) stack.push({ method: 'GET', path: key, fn });
        return app;
    };

    app.locals = Object.create(null);

    app.listen = (port, onListen) => {
        const server = createServer(app);
        return server.listen(port, onListen);
    };

    return app;
}

/* ---- body parsers (middleware) ---- */
express.json = () => (req, res, next) => { req.body = parseBody(req); next(); };
express.urlencoded = () => (req, res, next) => { req.body = parseBody(req); next(); };
express.text = () => (req, res, next) => { req.body = String(req.body || ''); next(); };

/* ---- static file serving ---- */
express.static = (root, opts = {}) => {
    const mw = (req, res, next) => {
        if (req.method !== 'GET' && req.method !== 'HEAD') return next();
        let rel = req.path;
        if (mw.__mount && rel.startsWith(mw.__mount)) rel = rel.slice(mw.__mount.length);
        else if (opts.prefix && rel.startsWith(opts.prefix)) rel = rel.slice(opts.prefix.length);
        if (rel === '/') rel = '/index.html';
        if (rel.includes('..')) return next();
        const full = root.replace(/\/$/, '') + rel;
        try {
            if (!fs.existsSync(full)) return next();
            const st = fs.statSync(full);
            if (st.isDirectory && st.isDirectory()) return next();
            const data = fs.readFileSync(full);
            res.type(mimeFor(full)).end(String(data));
        } catch (e) { next(e); }
    };
    mw.__mount = null;
    return mw;
};

/* ---- vhost: mount a sub-app for matching subdomains ---- */
express.vhost = (host, handler) => {
    const mw = (req, res, next) => {
        if (hostMatches(host, req.headers && req.headers.host)) handler(req, res, next);
        else next();
    };
    return mw;
};

/* register the built-in mini-EJS engine under the default extension */
export const defaultEngine = renderMiniEJS;
express.defaultEngine = renderMiniEJS;

export default express;
